using System.Collections.Generic;public class Solution{List<string>o=new();void F(string s,int p,long v,long last,string e,long t){if(p==s.Length){if(v==t)o.Add(e);return;}long n=0;for(int i=p;i<s.Length;i++){if(i>p&&s[p]=='0')break;n=n*10+s[i]-'0';string x=s.Substring(p,i-p+1);if(p==0)F(s,i+1,n,n,x,t);else{F(s,i+1,v+n,n,e+"+"+x,t);F(s,i+1,v-n,-n,e+"-"+x,t);F(s,i+1,v-last+last*n,last*n,e+"*"+x,t);}}}public IList<string> AddOperators(string s,int t){F(s,0,0,0,"",t);return o;}}
